import{_ as i,o as n,c as t,a2 as l}from"./chunks/framework.DBU8LMUS.js";const k=JSON.parse('{"title":"Profil & Data Diri","description":"","frontmatter":{"title":"Profil & Data Diri","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/profil.md","filePath":"latest/profil.md","lastUpdated":1786334463000}'),e={name:"latest/profil.md"};function r(o,a,s,d,u,m){return n(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="profil-data-diri" tabindex="-1">Profil &amp; Data Diri <a class="header-anchor" href="#profil-data-diri" aria-label="Permalink to &quot;Profil &amp; Data Diri&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p>Halaman profil menampilkan data diri Anda kepada pengunjung lain (sesuai pengaturan visibilitas). Modul ini menjelaskan cara melengkapi, mengedit, dan memanfaatkan fitur-fitur profil seperti foto, resume, tautan portofolio, dan status <strong>Open to Work</strong>.</p><h2 id="melihat-profil" tabindex="-1">Melihat Profil <a class="header-anchor" href="#melihat-profil" aria-label="Permalink to &quot;Melihat Profil&quot;">​</a></h2><h3 id="melihat-profil-sendiri" tabindex="-1">Melihat Profil Sendiri <a class="header-anchor" href="#melihat-profil-sendiri" aria-label="Permalink to &quot;Melihat Profil Sendiri&quot;">​</a></h3><ol><li>Masuk ke akun Anda.</li><li>Klik menu <strong>Profil Saya</strong> pada navigasi.</li><li>Halaman profil Anda akan tampil dengan data yang sudah diisi.</li></ol><h3 id="melihat-profil-alumni-lain" tabindex="-1">Melihat Profil Alumni Lain <a class="header-anchor" href="#melihat-profil-alumni-lain" aria-label="Permalink to &quot;Melihat Profil Alumni Lain&quot;">​</a></h3><ol><li>Buka halaman <strong>Direktori Alumni</strong>.</li><li>Klik kartu atau nama alumni yang ingin dilihat.</li><li>Profil alumni tersebut akan ditampilkan.</li></ol><h2 id="mengedit-profil" tabindex="-1">Mengedit Profil <a class="header-anchor" href="#mengedit-profil" aria-label="Permalink to &quot;Mengedit Profil&quot;">​</a></h2><h3 id="membuka-halaman-edit" tabindex="-1">Membuka Halaman Edit <a class="header-anchor" href="#membuka-halaman-edit" aria-label="Permalink to &quot;Membuka Halaman Edit&quot;">​</a></h3><ol><li>Pastikan Anda sudah masuk.</li><li>Klik menu <strong>Profil Saya</strong>, lalu klik tombol <strong>Edit Profil</strong>.</li><li>Anda akan diarahkan ke halaman pengeditan profil.</li></ol><h3 id="mengisi-data-profil" tabindex="-1">Mengisi Data Profil <a class="header-anchor" href="#mengisi-data-profil" aria-label="Permalink to &quot;Mengisi Data Profil&quot;">​</a></h3><p>Lengkapi atau perbarui bagian-bagian berikut:</p><ul><li><strong>Data pribadi</strong>: nama lengkap, angkatan, dan tahun lulus.</li><li><strong>Pekerjaan saat ini</strong>: jabatan dan nama perusahaan.</li><li><strong>Kontak</strong>: nomor telepon dan lokasi/kota.</li><li><strong>Tautan media sosial</strong>: profil LinkedIn, GitHub, atau lainnya (opsional).</li><li><strong>Keahlian (skills)</strong>: pilih keahlian yang relevan dan beri nilai 1–5 sesuai tingkat penguasaan.</li></ul><h3 id="menyimpan-perubahan" tabindex="-1">Menyimpan Perubahan <a class="header-anchor" href="#menyimpan-perubahan" aria-label="Permalink to &quot;Menyimpan Perubahan&quot;">​</a></h3><ol><li>Klik tombol <strong>Simpan</strong> di bagian bawah formulir.</li><li>Jika berhasil, Anda akan kembali ke halaman profil dengan data terbaru.</li></ol><h2 id="mengunggah-foto-profil" tabindex="-1">Mengunggah Foto Profil <a class="header-anchor" href="#mengunggah-foto-profil" aria-label="Permalink to &quot;Mengunggah Foto Profil&quot;">​</a></h2><ol><li>Buka halaman <strong>Edit Profil</strong>.</li><li>Pada bagian foto profil, klik <strong>Unggah Foto</strong>.</li><li>Pilih berkas gambar dari perangkat Anda.</li><li>Foto akan otomatis dikompresi dan diubah ukurannya (maksimal 512 piksel, kualitas 80%) sebelum diunggah.</li><li>Klik <strong>Simpan</strong> untuk menyimpan perubahan.</li></ol><div class="tip custom-block"><p class="custom-block-title">Rekomendasi</p><p>Gunakan foto formal atau semi-formal dengan pencahayaan baik. Hindari gambar terlalu besar karena akan diperkecil secara otomatis.</p></div><h2 id="mengunggah-resume-pdf" tabindex="-1">Mengunggah Resume (PDF) <a class="header-anchor" href="#mengunggah-resume-pdf" aria-label="Permalink to &quot;Mengunggah Resume (PDF)&quot;">​</a></h2><ol><li>Buka halaman <strong>Edit Profil</strong>.</li><li>Pada bagian resume, klik <strong>Unggah Resume</strong>.</li><li>Pilih berkas <strong>PDF</strong> dari perangkat Anda.</li><li>Pastikan ukuran berkas <strong>tidak lebih dari 2 MB</strong>. Aplikasi akan menolak berkas yang melebihi batas.</li><li>Klik <strong>Simpan</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">Batas Ukuran</p><p>Resume maksimal <strong>2 MB</strong> dan harus berformat <strong>PDF</strong>. Perkecil berkas Anda terlebih dahulu jika melebihi batas (misalnya dengan kompresi PDF atau menghapus gambar besar di dalamnya).</p></div><h2 id="menambahkan-tautan-portofolio" tabindex="-1">Menambahkan Tautan Portofolio <a class="header-anchor" href="#menambahkan-tautan-portofolio" aria-label="Permalink to &quot;Menambahkan Tautan Portofolio&quot;">​</a></h2><ol><li>Buka halaman <strong>Edit Profil</strong>.</li><li>Pada kolom <strong>Tautan Portofolio</strong>, masukkan alamat lengkap (misalnya <code>https://portofolio-saya.com</code>).</li><li>Klik <strong>Simpan</strong>.</li></ol><p>Tautan portofolio akan ditampilkan sebagai tombol di halaman profil Anda.</p><h2 id="mengatur-status-open-to-work" tabindex="-1">Mengatur Status Open to Work <a class="header-anchor" href="#mengatur-status-open-to-work" aria-label="Permalink to &quot;Mengatur Status Open to Work&quot;">​</a></h2><p>Fitur <strong>Open to Work</strong> menandakan bahwa Anda sedang terbuka terhadap tawaran pekerjaan.</p><h3 id="menyalakan-status" tabindex="-1">Menyalakan Status <a class="header-anchor" href="#menyalakan-status" aria-label="Permalink to &quot;Menyalakan Status&quot;">​</a></h3><ol><li>Buka halaman <strong>Edit Profil</strong>.</li><li>Aktifkan sakelar (toggle) <strong>Open to Work</strong>.</li><li>Klik <strong>Simpan</strong>.</li></ol><h3 id="mematikan-status" tabindex="-1">Mematikan Status <a class="header-anchor" href="#mematikan-status" aria-label="Permalink to &quot;Mematikan Status&quot;">​</a></h3><ol><li>Buka halaman <strong>Edit Profil</strong>.</li><li>Nonaktifkan sakelar <strong>Open to Work</strong>.</li><li>Klik <strong>Simpan</strong>.</li></ol><p>Setelah diaktifkan, status Anda akan ditampilkan di profil dan dapat terlihat oleh pengguna lain di direktori.</p><h2 id="memberi-dukungan-keahlian-endorsement" tabindex="-1">Memberi Dukungan Keahlian (Endorsement) <a class="header-anchor" href="#memberi-dukungan-keahlian-endorsement" aria-label="Permalink to &quot;Memberi Dukungan Keahlian (Endorsement)&quot;">​</a></h2><p>Endorsement adalah bentuk dukungan dari alumni lain terhadap keahlian yang Anda miliki.</p><ol><li>Buka profil alumni lain dari <strong>Direktori Alumni</strong>.</li><li>Pada bagian <strong>Keahlian</strong>, temukan keahlian yang ingin didukung.</li><li>Klik tombol <strong>Dukung</strong> (endorse) pada keahlian tersebut.</li></ol><div class="warning custom-block"><p class="custom-block-title">Catatan</p><p>Anda tidak dapat mendukung keahlian pada profil Anda sendiri. Endorsement hanya dapat diberikan oleh alumni lain yang sudah masuk.</p></div><h2 id="visibilitas-profil" tabindex="-1">Visibilitas Profil <a class="header-anchor" href="#visibilitas-profil" aria-label="Permalink to &quot;Visibilitas Profil&quot;">​</a></h2><p>Profil memiliki pengaturan visibilitas berikut:</p><table tabindex="0"><thead><tr><th>Visibilitas</th><th>Keterangan</th></tr></thead><tbody><tr><td><strong>Publik</strong></td><td>Dapat dilihat siapa saja, termasuk pengunjung yang belum masuk.</td></tr><tr><td><strong>Khusus Alumni</strong></td><td>Hanya dapat dilihat pengguna yang sudah masuk.</td></tr><tr><td><strong>Pribadi</strong></td><td>Hanya dapat dilihat oleh Anda dan admin.</td></tr></tbody></table><p>Pengaturan ini dapat diubah melalui halaman <strong>Edit Profil</strong>.</p><p>Lanjutkan ke <a href="/webapps/latest/direktori">Direktori Alumni</a> untuk mencari dan terhubung dengan alumni lain.</p>',41)])])}const g=i(e,[["render",r]]);export{k as __pageData,g as default};
